def win_rates(df):
    rates = {}
    for rep in sorted(df["Owner"].unique()):
        mine = df[df["Owner"] == rep]
        won = int((mine["Outcome"] == "won").sum())
        lost = int((mine["Outcome"] == "lost").sum())
        total = won + lost
        # No closed deals for this rep: rate is undefined, so report None instead of dividing by zero
        rates[rep] = round(won / total, 4) if total else None
    return rates

import re


def _norm_stage(value):
    # "Closed - Won", "Closed  Won", "closed-won" -> "closed won"
    return re.sub(r"[\s\-_]+", " ", str(value)).strip().lower()


