import logging
import os

import pandas as pd


def load_export(path):
    if not os.path.isfile(path):
        logging.warning("Export file not found, returning empty DataFrame: %s", path)
        return pd.DataFrame()
    return pd.read_csv(path, encoding="utf-8", dtype=str, keep_default_na=False)
